import {BASE} from './express-entry.js';
const offer=BASE+'documents/job-offer.html';
export const qualificationGuides={
 fswOffer:{title:'Does my job offer qualify?',note:'PGWP or another open work permit + an ordinary job offer does not qualify by itself. For a PGWP holder, the employer generally needs a positive LMIA supporting the offer. A valid PGWP can still authorize work and that work may count as Canadian experience.',items:[
 'A written offer from one eligible employer for paid, continuous, non-seasonal work of at least 30 hours per week in TEER 0–3.',
 'The employer is offering at least one year of employment after you become a permanent resident.',
 'One qualifying route applies: a new positive LMIA naming you and the position; OR you work for the employer named on your LMIA-based permit with the required continuing work authorization; OR you qualify under the employer-specific LMIA-exempt route described below.',
 'For the employer-specific LMIA-exempt route: the employer is named on your valid permit, you currently work for them, you have at least one year of full-time equivalent experience with them, and the exemption is eligible under IRCC’s rules. A PGWP alone does not satisfy this route.',
 'You can perform the offered work and obtain required licensing or certification.'
 ],source:offer,foot:'An ordinary employment contract or permanent position is not enough. Physician public-policy exceptions require individual review.'},
 authorized:{title:'Does my work authorization qualify?',note:'A valid PGWP counts as authorization to work, subject to its conditions. It does not automatically make a job offer qualifying arranged employment.',items:['Your current immigration status permits you to work in Canada.','You comply with the permit’s conditions and any occupation or employer restrictions. If relying on maintained status or another exception, confirm that you may continue working.'],source:offer},
 cecWork:{title:'Does my Canadian experience qualify?',note:'Paid skilled work on a PGWP can count. Your job offer does not need an LMIA for the experience itself to count.',items:['At least 12 months and 1,560 hours of eligible work within the last 3 years; count no more than 30 hours per week. Equivalent part-time work can count.','The work was paid, in TEER 0–3, and matched the NOC lead statement and most main duties.','You were physically in Canada, working for a Canadian employer, and authorized to work under temporary resident status.','Exclude work while a full-time student and self-employment, unless a specific IRCC exception applies.'],source:BASE+'who-can-apply/canadian-experience-class.html',foot:'CEC experience does not need to be continuous. Qualifying work can span employers and occupations. Special rules exist for certain physicians.'},
 fswWork:{title:'Does my continuous skilled work qualify?',items:['At least one continuous year of paid work, totaling at least 1,560 hours; count no more than 30 hours per week. Equivalent part-time work can count.','The qualifying year was within the last 10 years, in Canada or abroad.','The work was in the same primary NOC occupation in TEER 0–3, matching the lead statement and most main duties.'],note:'Paid student work can qualify for FSW when it is continuous and meets the other requirements. This differs from CEC.',source:BASE+'who-can-apply/federal-skilled-workers.html'},
 tradeWork:{title:'Does my skilled trade experience qualify?',items:['At least two years and 3,120 hours of paid full-time equivalent work in the last 5 years, counting no more than 30 hours per week.','Experience is in the same eligible NOC: major groups 72 (excluding 726), 73, 82, 83, 92, 93 (excluding 932), minor group 6320 or unit group 62200.','You meet the NOC job requirements and performed its lead statement and most main duties.','You were qualified to practise the trade independently where the work was gained. Exclude student work.'],source:BASE+'who-can-apply/federal-skilled-trades.html'},
 tradeOffer:{title:'Does my trade job offer qualify?',note:'A PGWP alone does not exempt the offer from the LMIA requirements. A qualifying Canadian trade certificate can satisfy the FST offer-or-certificate requirement instead.',items:['An offer from up to two eligible employers for continuous, paid, full-time work totaling at least 30 hours per week for at least one year.','The offer is for an eligible FST skilled trade occupation.','The offer is supported by a qualifying positive LMIA, or all of IRCC’s existing LMIA-based or employer-specific LMIA-exempt permit conditions apply. For the exempt route, you must currently work for the named employer(s) and have at least one year of full-time equivalent experience with them.'],source:offer},
 certificate:{title:'Is this a qualifying trade certificate?',items:['Issued by a Canadian provincial, territorial or federal authority responsible for the trade.','Certifies that you have passed the required certification exam and meet the requirements to practise that skilled trade.'],note:'A college trade diploma, apprenticeship attendance certificate or employer training certificate is not automatically a certificate of qualification.',source:BASE+'who-can-apply/federal-skilled-trades.html'},
 educationValid:{title:'Can I claim education points?',items:['You completed the credential.','It is a Canadian credential, or you have a valid ECA for immigration from an IRCC-designated organization showing its Canadian equivalency.','For foreign education, the ECA is less than five years old when creating your profile and submitting the application.'],source:BASE+'documents/education-assessed.html',foot:'Choose the Canadian-equivalent level shown on the ECA, which may differ from the original credential title.'},
 funds:{title:'Do I need settlement funds?',items:['CEC does not require proof of settlement funds.','For FSW/FST, an exemption requires both current authorization to work in Canada and a valid qualifying job offer. A PGWP plus an ordinary job is not enough.','If no exemption applies, check the current IRCC amount for your family size and ensure funds meet IRCC’s availability and documentation rules.'],source:BASE+'documents/proof-funds.html',foot:'A work permit alone does not provide the funds exemption. Family-size thresholds change; use the official current table.'}
};
